/* harmony default export */ __webpack_exports__["default"] = ({
  onLoad(e) {
    this.id = e.id || '';
    this.getCouponDetail();
  },
  data() {
    return {
      id: '',
      info: {},
      goods_info: {},
      is_show: false,
      value: false
    };
  },
  methods: {
    getCouponDetail() {
      this.$api.couponDetail({
        id: this.id
      }).then(res => {
        if (res.code == 1) {
          this.info = res.data;
        } else {
          this.$u.toast(res.msg);
        }
      });
    },
    clickSwiper(index, item) {
      console.log(index, item);
      this.goPage('/pages/hotel/detail?id=' + item.id);
    },
    collect(id, index, status) {
      this.$api.optionCollect({
        goods_id: id,
        type: 0
      }).then(res => {
        if (res.code) {
          if (status) {
            this.$u.toast('取消收藏成功');
            this.$set(this.info.goods[index], 'isCollect', 0);
          } else {
            this.$u.toast('添加收藏成功');
            this.$set(this.info.goods[index], 'isCollect', 1);
          }
        } else {
          this.$u.toast(res.msg);
        }
      });
    },
    toBooking(id) {
      this.$api.houseDetail({
        id: id
      }).then(res => {
        if (res.code == 1) {
          this.goods_info = res.data;
          this.is_show = true;
          setTimeout(() => {
            this.value = true;
          }, 100);
        } else {
          this.$u.toast(res.msg);
        }
      });
    },
    calendarConfirm(e, dom) {
      if (JSON.stringify(e) == '{}') {
        this.$u.toast('请选择入住和离店日期');
        return;
      }
      if (!dom) {
        return;
      }
      this.goPage('/pages/hotel/booking?id=' + this.goods_info.id + '&start_time=' + e.start + '&end_time=' + e.end);
    },
    give() {
      this.$api.drawCoupon({
        id: this.info.id
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code == 1) {
          this.is_update = true;
          this.getCouponDetail();
        }
      });
    }
  }
});

